              {[...MEMBERS].sort((a, b) => yearEndSummary.attendanceStats[a.id] - yearEndSummary.attendanceStats[b.id]).map(m => {
                const count = yearEndSummary.attendanceStats[m.id];
                const isEligible = count <= MAX_ABSENCES_FOR_BONUS;
                return (
