                    </span>
                    <span className="mario-font text-[6px] opacity-70">{count} MISS</span>
                  </div>
                );
              })}
            </div>
            <div className="mt-2 pt-1 border-t border-white/10 text-center">
               <span className="mario-font text-[5px] text-blue-300">BEST PLAYER STATUS</span>
            </div>
          </div>
        </div>
